-- Idempotent install for metrics.thresholds
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS metrics;

CREATE SEQUENCE IF NOT EXISTS metrics.thresholds_row_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS metrics.thresholds (
    row_id integer NOT NULL,
    day_of_event integer NOT NULL,
    hour_of_event integer NOT NULL,
    value_from numeric(10,2) NOT NULL,
    value_to numeric(10,2) NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    entry_date timestamp without time zone DEFAULT now() NOT NULL
);

ALTER TABLE metrics.thresholds ALTER COLUMN row_id SET DEFAULT nextval('metrics.thresholds_row_id_seq'::regclass);
ALTER SEQUENCE metrics.thresholds_row_id_seq OWNED BY metrics.thresholds.row_id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE metrics.thresholds);
SELECT row_id, day_of_event, hour_of_event, value_from, value_to, is_active, entry_date FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM metrics.thresholds);
DROP TABLE _stg_load;

SELECT setval('metrics.thresholds_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM metrics.thresholds),1), (SELECT count(*) FROM metrics.thresholds) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'metrics' AND c.relname = 'thresholds'
          AND con.conname = 'pk_thresholds') THEN
        ALTER TABLE ONLY metrics.thresholds
    ADD CONSTRAINT pk_thresholds PRIMARY KEY (day_of_event, hour_of_event, value_from, value_to);
    END IF;
END $do$;
